@Entity
class Order {
    @Id @GeneratedValue Long id;
    String status;
    public boolean equals(Object o) {
        return o instanceof Order && Objects.equals(id, ((Order) o).id);
    }
    public int hashCode() { return Objects.hash(id); }
}

Set<Order> orders = new HashSet<>();
Order o = new Order(); // id is null before persist()
orders.add(o);
entityManager.persist(o); // id is now assigned, e.g. 7
System.out.println(orders.contains(o));

@Entity
class Order {
