@Entity class Order {
    @Id Long id;
    @ManyToOne
    Customer customer; // owning side
}
@Entity class Customer {
    @Id Long id;
    @OneToMany(mappedBy = "customer")
    List<Order> orders = new ArrayList<>(); // inverse side
}

Customer c = customerRepo.findById(1L).get();
Order o = orderRepo.findById(5L).get();
c.getOrders().add(o); // only updating the inverse side
// no change to o.customer

